        deal(address(token), address(victim), depositAmount);

        // Forcefully grant the riskControl role by overwriting the storage slot.
        // Assuming owner is in slot 0, riskControl is likely in slot 1.
        vm.store(address(victim), bytes32(uint256(1)), bytes32(uint256(uint160(riskControl))));
